from django.db import migrations, models


from django.utils.text import slugify


def fill_slugs(apps, schema_editor):
    """each existing artist and band's slug from its name, -2, -3... on a clash"""
    for name in ("Artist", "Band"):
        model = apps.get_model("core", name)
        taken = set()
        for record in model.objects.order_by("pk"):
            base = (slugify(record.name) or "act")[:110]
            slug, n = base, 2
            while slug in taken:
                slug, n = f"{base}-{n}", n + 1
            taken.add(slug)
            model.objects.filter(pk=record.pk).update(slug=slug)


